def parse(
    self,
    conversation: "Conversation",
    max_length: int,
    preformatted: bool = False,
    train_only_last_turn: bool = False,
) -> List[torch.Tensor]:
    # conversation = process_harmony_conversations(conversation)
    if not preformatted:
        prompt_text = ""
        for j, message in enumerate(conversation):
            if j == 0 and (
                message["role"] != "system"
                or message["role"] != "assistant_reasoning_effort"
            ):
                prompt_text = self.build_single_turn_prompt(
                    prompt_text,
                    "assistant_reasoning_effort",
                    self.default_reasoning_level,
                )
            prompt_text = self.build_single_turn_prompt(
                prompt_text, message["role"], message["content"]
            )
        conversation = prompt_text

def guarded_connect(inst: socket.socket, *args: Any) -> None:
    host = host_from_connect_args(args)
    if host in allowed_ip_hosts_and_hostnames or (
        _is_unix_socket(inst.family) and allow_unix_socket
    ):
        return _true_connect(inst, *args)

    if host and networks and is_ipaddress(host):
        ip = ipaddress.ip_address(host)
        if any(ip in net for net in networks):
            return _true_connect(inst, *args)

    raise SocketConnectBlockedError(allowed_list, host)

